    public void destroyCache(Cache cache) {
        if (cache instanceof CacheWrapper) {
            cache = ((CacheWrapper) cache).getWrappedCache();
        }

        final ClusteredCache clustered = (ClusteredCache) cache;
        clustered.destroy();
    }

